function validate([favorite]) {
  if (!Array.isArray(favorite) || favorite.length < 2 || favorite.length > 100000) return 'favorite needs 2 to 100000 entries.';
  const n = favorite.length;
  for (let i = 0; i < n; i++) {
    if (!Number.isInteger(favorite[i]) || favorite[i] < 0 || favorite[i] >= n) return 'Each favorite[i] is an employee number from 0 to n - 1.';
    if (favorite[i] === i) return 'No employee is their own favorite.';
  }
  return null;
}

