function maximumInvitations(favorite) {
  const n = favorite.length;
  const indegree = new Array(n).fill(0);
  for (const target of favorite) {
    indegree[target]++;
  }
  const depth = new Array(n).fill(0);
  const queue = [];
  for (let i = 0; i < n; i++) {
    if (indegree[i] === 0) {
      queue.push(i);
    }
  }
  let head = 0;
  while (head < queue.length) {
    const person = queue[head++];
    const next = favorite[person];
    depth[next] = Math.max(depth[next], depth[person] + 1);
    indegree[next]--;
    if (indegree[next] === 0) {
      queue.push(next);
    }
  }
  let longestCycle = 0;
  let pairTotal = 0;
  for (let i = 0; i < n; i++) {
    if (indegree[i] === 0) {
      continue;
    }
    let length = 0;
    let current = i;
    while (indegree[current] !== 0) {
      indegree[current] = 0;
      length++;
      current = favorite[current];
    }
    if (length === 2) {
      pairTotal += depth[i] + depth[favorite[i]] + 2;
    } else {
      longestCycle = Math.max(longestCycle, length);
    }
  }
  return Math.max(longestCycle, pairTotal);
}

