function maximumInvitations(favorite) {
  // Build every seating order around the table (smallest guest first to skip rotations),
  // pruning a guest as soon as both neighbours are known and neither is their favorite.
  const n = favorite.length;
  const seats = [];
  const used = new Array(n).fill(false);
  const happy = (guest, left, right) => favorite[guest] === left || favorite[guest] === right;
  let best = 0;
  const grow = () => {
    const k = seats.length;
    if (k === 2 && favorite[seats[0]] === seats[1] && favorite[seats[1]] === seats[0]) best = Math.max(best, 2);
    if (k >= 3 && happy(seats[k - 1], seats[k - 2], seats[0]) && happy(seats[0], seats[k - 1], seats[1])) best = Math.max(best, k);
    for (let p = seats[0] + 1; p < n; p++) {
      if (used[p]) continue;
      if (k >= 2 && !happy(seats[k - 1], seats[k - 2], p)) continue;
      used[p] = true;
      seats.push(p);
      grow();
      seats.pop();
      used[p] = false;
    }
  };
  for (let first = 0; first < n; first++) {
    seats.push(first);
    used[first] = true;
    grow();
    used[first] = false;
    seats.pop();
  }
  return best;
}

