function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : int(2, 9);
  if (size === 'small' && rand() < 0.4) {
    // Fully random favorites.
    return [Array.from({ length: n }, (_, i) => { const f = int(0, n - 2); return f >= i ? f + 1 : f; })];
  }
  // Some cycles (often of length 2), then trees hanging off them, with labels shuffled.
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = int(0, i); [order[i], order[j]] = [order[j], order[i]]; }
  const favorite = new Array(n);
  const bigCycle = size === 'large' ? 400 : 6;
  let placed = 0;
  const cycles = int(1, size === 'large' ? 8 : 3);
  for (let c = 0; c < cycles; c++) {
    const length = rand() < 0.55 ? 2 : int(3, bigCycle);
    if (placed + length > n) break;
    for (let t = 0; t < length; t++) favorite[order[placed + t]] = order[placed + (t + 1) % length];
    placed += length;
  }
  if (placed === 0) { favorite[order[0]] = order[1]; favorite[order[1]] = order[0]; placed = 2; }
  for (let idx = placed; idx < n; idx++) {
    favorite[order[idx]] = rand() < 0.6 ? order[idx - 1] : order[int(0, idx - 1)];
  }
  return [favorite];
}
